-- 429: WASSCE English letter and report writing multiple-choice set A and structured question (batch sprint 1).
-- Original BrillaPrep curriculum-aligned practice content; not official WAEC material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_429_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_429_guard;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_001' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A formal letter to a public officer must contain' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. the writer''s address and the recipient''s address","B. only the recipient''s address","C. no address at all","D. only a telephone number"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Formal letters carry two addresses — the writer''s and the recipient''s — plus the date; informal letters carry only the writer''s address.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_002' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The most suitable salutation for a formal letter written to a stranger is' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. My dear Kofi,","B. Dear Sir,","C. Hello Sir,","D. Dearest friend,"]' AND q.correct_answer IS 'B' AND q.explanation IS 'A stranger in an official position is addressed "Dear Sir" or "Dear Madam"; the other salutations are informal or too casual.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Choose' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_002' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_003' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which subscription is appropriate for a letter to a close friend?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Yours faithfully,","B. Yours sincerely,","C. Yours ever,","D. Yours obediently,"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Letters to friends close warmly with subscriptions such as "Yours ever"; "faithfully" and "sincerely" belong to formal letters, and "obediently" is servile.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Choose' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_003' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_mcq_004' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A report is usually written in order to' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. entertain readers with an exciting story","B. describe the writer''s personal feelings","C. advertise a new product to the public","D. present facts and findings to the person or body that asked for them"]' AND q.correct_answer IS 'D' AND q.explanation IS 'A report is commissioned: someone in authority asks for facts, findings and often recommendations on a specific matter.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_mcq_004' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_eng_s1_let_st_001' AND NOT (q.topic_id IS 'topic_wassce_english_letter' AND q.subject_id IS 'subj_wassce_english' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The headmistress has asked you, as senior prefect, to write a report on the damage done to classroom furniture during the term. Answer the following questions about the report you would write.' AND q.question_type IS 'structured' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '(a) A title or heading, and clearly labelled sections such as the introduction, findings and recommendations. (b) Report on the Damage Done to Classroom Furniture During the Term. (c) A description of the furniture that was damaged, and the extent and possible causes of the damage.' AND q.explanation IS 'The report must suit its official purpose: (a) a title and labelled sections; (b) a title naming the subject of the report; (c) findings describing what was damaged and how badly or why.' AND q.difficulty IS 'medium' AND q.points IS '10' AND q.marks IS '10' AND q.time_limit IS '300' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Plan' AND q.assessment_objective IS NULL AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_eng_s1_let_st_001' AND NOT (r.batch_id IS 'wassce-english-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep WASSCE English practice content; not official WAEC material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_let_st_001_a' AND NOT (sp.id IS 'sqp_q_eng_s1_let_st_001_a' AND sp.question_id IS 'q_eng_s1_let_st_001' AND sp.part_label IS 'a' AND sp.part_text IS 'State two features of the format of an official report.' AND sp.marks IS '3' AND sp.correct_answer IS 'A title or heading, and clearly labelled sections such as the introduction, findings and recommendations.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '0')) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_let_st_001_b' AND NOT (sp.id IS 'sqp_q_eng_s1_let_st_001_b' AND sp.question_id IS 'q_eng_s1_let_st_001' AND sp.part_label IS 'b' AND sp.part_text IS 'Write a suitable title for this report.' AND sp.marks IS '3' AND sp.correct_answer IS 'Report on the Damage Done to Classroom Furniture During the Term.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '1')) THEN 1 ELSE 0 END;
INSERT INTO _migration_429_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = 'sqp_q_eng_s1_let_st_001_c' AND NOT (sp.id IS 'sqp_q_eng_s1_let_st_001_c' AND sp.question_id IS 'q_eng_s1_let_st_001' AND sp.part_label IS 'c' AND sp.part_text IS 'State two kinds of information the findings section of the report should contain.' AND sp.marks IS '4' AND sp.correct_answer IS 'A description of the furniture that was damaged, and the extent and possible causes of the damage.' AND sp.explanation IS NULL AND sp.answer_type IS 'text' AND sp.display_order IS '2')) THEN 1 ELSE 0 END;
